import{_ as s,o as p,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const l="/assets/116_blobid12.CfwILWHc.png",i="/assets/109_blobid13.BB6PeaZd.png",a="/assets/107_blobid14.CTFdaESP.png",o="/assets/101_blobid15.ujk11wey.png",n="/assets/111_blobid16.uSYwuGae.png",c="/assets/110_blobid17.tGWpG4nt.png",m="/assets/112_blobid18.DCxdq7iU.png",d="/assets/117_blobid19.CNt5cWIO.png",_="/assets/119_blobid20.E3tE7v2T.png",u="/assets/102_blobid21.DSZPThc2.png",g="/assets/103_blobid22.YIScUMq7.png",b="/assets/118_blobid23.BwiBm9aM.png",C=JSON.parse('{"title":"Linux系统锐速安装教程","description":"","frontmatter":{"title":"Linux系统锐速安装教程"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/install-serverspeeder.md","filePath":"ops-knowledge-base/operating-system/linux/install-serverspeeder.md","lastUpdated":1788259091000}'),f={name:"ops-knowledge-base/operating-system/linux/install-serverspeeder.md"};function h(v,e,S,x,k,y){return p(),t("div",null,[...e[0]||(e[0]=[r('<p>注意事项：锐速安装的前提是确保网卡为 eth 系列</p><p>步骤一：安装推荐版本内核，安装完成重启机器</p><p>步骤二：重启后核实内核安装正确，直接下载91YUN锐速安装脚本，会自动执行</p><p>一.修改网卡名称</p><p>1.使用ip address命令查看网卡名</p><p><img src="'+l+'" alt=""></p><ol start="2"><li>进到到网卡配置文件目录，使用ls命令查看网卡配置文件名称</li></ol><ul><li>cd /etc/sysconfig/network-scripts/</li></ul><p><img src="'+i+'" alt=""></p><ol start="3"><li>使用mv命令更改网卡配置文件名，ls查看是否修改成功</li></ol><ul><li>mv ifcfg-***（*为原网卡名） ifcfg-eth*（如果是多网卡，eth后的数字可以向后顺延）</li></ul><p><img src="'+a+'" alt=""></p><ol start="4"><li>更改文件内网卡名(仅需修改网卡名，如有引号也需要删除)</li></ol><ul><li>vi ifcfg-eth*</li></ul><p><img src="'+o+'" alt=""></p><p>按i键进入文本输入模式，对网卡名进行修改</p><p>DEVICE=eth*</p><p>NAME=eth*</p><p><img src="'+n+'" alt=""><img src="'+c+'" alt=""></p><p>5.按ESC键退出文本输入模式，按Shift+:(冒号键)进入末行模式，输入wq回车保存修改内容。</p><p>6.使用cat命令查看是否修改成功。</p><ul><li>cat ifcfg-eth0</li></ul><p><img src="'+m+'" alt=""></p><p>7.如果有Range文件形式的网卡配置文件，按以下命令进行修改，eth*名称需要和主网卡名一致。</p><ul><li>mv ifcfg-***-range0 ifcfg-eth*-range0</li></ul><ol start="8"><li><p>重启 reboot</p></li><li><p>检查网卡名是否修改成功</p></li></ol><ul><li>ip address</li></ul><p><img src="'+d+'" alt=""></p><p>二.安装锐速</p><p>1.修改指定优化内核：</p><p>CentOS7.x内核更换为： 3.10.0-229.1.2.el7.x86_64</p><ul><li>rpm -ivh <a href="http://soft.91yun.org/ISO/Linux/CentOS/kernel/kernel-3.10.0-229.1.2.el7.x86_64.rpm" target="_blank" rel="noreferrer">http://soft.91yun.org/ISO/Linux/CentOS/kernel/kernel-3.10.0-229.1.2.el7.x86_64.rpm</a> --force</li></ul><p>2.查看内核是否安装成功</p><ul><li>rpm -qa | grep kernel</li></ul><p><img src="'+_+'" alt=""></p><p>3.重启 reboot</p><p>4.查看内核是否更换成功</p><ul><li>uname -r</li></ul><p><img src="'+u+'" alt=""></p><p>5.下载安装脚本并自动执行：</p><p>锐速安装方法 ：</p><ul><li>wget -N --no-check-certificate <a href="https://github.com/91yun/serverspeeder/raw/master/serverspeeder.sh" target="_blank" rel="noreferrer">https://github.com/91yun/serverspeeder/raw/master/serverspeeder.sh</a> &amp;&amp; yum install net-tools &amp;&amp; bash serverspeeder.sh</li></ul><p><img src="'+g+'" alt="">这里输入y回车继续</p><p>6.安装完成后，查询锐速运行状态：</p><ul><li>/serverspeeder/bin/serverSpeeder.sh status</li></ul><p><img src="'+b+'" alt=""></p><p>7.设置锐速开机自启动：</p><ul><li>echo &quot;service serverSpeeder start&quot; &gt;&gt; /etc/rc.d/rc.local &amp;&amp; chmod +x /etc/rc.d/rc.local</li></ul><p>报错解决：</p><p>serverspeeder.sh: line 141: ifconfig: command not found</p><p>出现此问题的原因绝大多数情况下可能都是系统没有附带ipconfig；</p><p>因此这个时候只需要我们使用命令安装ipconfig即可，命令如下：</p><p>yum install upgrade</p><p>yum install net-tools</p><p>常用命令：</p><p>重启锐速：</p><p>/serverspeeder/bin/serverSpeeder.sh restart</p><p>锐速运行状态：</p><p>/serverspeeder/bin/serverSpeeder.sh status</p><p>卸载锐速：</p><p>chattr -i /serverspeeder/etc/apx* &amp;&amp; /serverspeeder/bin/serverSpeeder.sh uninstall -f</p>',61)])])}const E=s(f,[["render",h]]);export{C as __pageData,E as default};
